<?php
declare(strict_types=1); define('SAAS_NO_GLOBAL_NAV',true); require_once __DIR__.'/finance.php'; require_finance_admin(); $pdo=db();
$rows=$pdo->query("SELECT u.name,COUNT(c.id) uploads,SUM(c.status='approved') approved,ROUND(100*SUM(c.status='approved')/NULLIF(COUNT(c.id),0),1) approval_rate,ROUND(AVG((SELECT COUNT(*) FROM content_status_history h WHERE h.content_id=c.id AND h.new_status='changes_requested')),1) avg_revisions FROM users u LEFT JOIN content c ON c.employee_id=u.id WHERE u.role='employee' GROUP BY u.id,u.name ORDER BY u.name")->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Content Performance</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="content_performance.php">▥ <span>Content performance</span></a><a class="saas-nav" href="master_calendar.php">◷ <span>Master calendar</span></a><a class="saas-nav" href="client_report.php">▤ <span>Client report</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Content Performance</h1><section class="saas-card"><table class="saas-table"><thead><tr><th>Employee</th><th>Uploads</th><th>Approval rate</th><th>Avg revisions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['name'])?></td><td><?=e((string)$row['uploads'])?></td><td><?=e((string)($row['approval_rate']??0))?>%</td><td><?=e((string)($row['avg_revisions']??0))?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
